SELECT (SELECT group_concat(name, ',') FROM (SELECT name FROM sqlite_schema WHERE type='table' AND name GLOB 'db[0-9]*' ORDER BY CAST(substr(name,3) AS INTEGER))), (SELECT count(*) FROM db1)+(SELECT count(*) FROM db2)+(SELECT count(*) FROM db3)+(SELECT count(*) FROM db4)+(SELECT count(*) FROM db5)+(SELECT count(*) FROM db6)+(SELECT count(*) FROM db7)+(SELECT count(*) FROM db8)+(SELECT count(*) FROM db9)+(SELECT count(*) FROM db10)+(SELECT count(*) FROM db11)+(SELECT count(*) FROM db12)+(SELECT count(*) FROM db13)+(SELECT count(*) FROM db14);